    private State $state = State::IDLE;
    private SplFileObject $outputFile;


    public function execute(string $outputFilename, float $target): void
    {
        $target = $target * 1024 * 1024;

        while ($this->state !== State::COMPLETE) {
            $this->state = match ($this->state) {
                State::IDLE => $this->createOutputFile($outputFilename),
                State::WRITING => $this->writeBlock(),
                State::CHECKING => $this->hasSizeMetTarget($target),
            };
        }
    }

    private function createOutputFile(string $outputFilename): State
    {
        $this->outputFile = new SplFileObject($outputFilename, 'a');

        return State::WRITING;
    }

    private function writeBlock(): State
    {
        $this->outputFile->fwrite($this->block);

        return State::CHECKING;
    }

    private function hasSizeMetTarget(float $target): State
    {
        if ($this->outputFile->ftell() <= $target) {
            return State::WRITING;
        }

        return State::COMPLETE;
    }
}
